partial class ThebestRGB {
 TcpListener mobileListener;CancellationTokenSource mobileStop;string mobileAddress="";
 void StartMobileRemote(){
  try{
   EnsureMobileFirewallRule();
   IPAddress address=Dns.GetHostEntry(Dns.GetHostName()).AddressList.FirstOrDefault(a=>a.AddressFamily==AddressFamily.InterNetwork&&!IPAddress.IsLoopback(a));string ip=address==null?null:address.ToString();
   if(string.IsNullOrEmpty(ip))return;
   mobileAddress="http://"+ip+":18765/";mobileListener=new TcpListener(IPAddress.Any,18765);mobileListener.Start();mobileStop=new CancellationTokenSource();Task.Run(()=>MobileLoop(mobileStop.Token));
  }catch{mobileAddress="";}
 }
 void EnsureMobileFirewallRule(){try{using(var command=Process.Start(new ProcessStartInfo("netsh","advfirewall firewall add rule name=\"ThebestRGB controle pelo celular\" dir=in action=allow protocol=TCP localport=18765 profile=any remoteip=localsubnet"){UseShellExecute=false,CreateNoWindow=true})){command.WaitForExit(3000);}}catch{}}
 string MobileAddresses(){return string.Join("\r\n",NetworkInterface.GetAllNetworkInterfaces().Where(n=>n.OperationalStatus==OperationalStatus.Up).SelectMany(n=>n.GetIPProperties().UnicastAddresses).Where(a=>a.Address.AddressFamily==AddressFamily.InterNetwork&&!IPAddress.IsLoopback(a.Address)).Select(a=>"http://"+a.Address+":18765/").Distinct().ToArray());}
 async Task MobileLoop(CancellationToken token){try{while(!token.IsCancellationRequested){TcpClient client;try{client=await mobileListener.AcceptTcpClientAsync();}catch{break;}Task.Run(()=>MobileRequest(client));}}catch{}}
 void MobileRequest(TcpClient client){using(client)try{NetworkStream stream=client.GetStream();var reader=new StreamReader(stream,Encoding.ASCII);string first=reader.ReadLine();if(string.IsNullOrEmpty(first)){return;}string[] parts=first.Split(' ');string resource=parts.Length>1?parts[1]:"/";string line;while(!string.IsNullOrEmpty(line=reader.ReadLine())){}Uri uri=new Uri("http://local"+resource);if(uri.AbsolutePath.ToLowerInvariant()=="/set"){string hex=(Uri.UnescapeDataString(uri.Query).Replace("?color=","").Split('&')[0]??"").Trim().TrimStart('#');int value,mode;string modeText=uri.Query.Split('&').FirstOrDefault(x=>x.StartsWith("mode="));int.TryParse(modeText==null?"":modeText.Substring(5),out mode);if(hex.Length==6&&int.TryParse(hex,System.Globalization.NumberStyles.HexNumber,null,out value)){Color c=Color.FromArgb((value>>16)&255,(value>>8)&255,value&255);BeginInvoke(new Action(async delegate{if(busy)return;SetGlobal(c);if(mode>=0&&mode<EffectLibrary.Names.Length)effectMode.SelectedIndex=mode;await ApplyCards(cards.Where(card=>card.State.Included).ToList());}));WriteMobile(stream,"ok");}else WriteMobile(stream,"Cor inválida",400);return;}WriteMobile(stream,MobilePage(),200,"text/html; charset=utf-8");}catch{}}
 static void WriteMobile(NetworkStream stream,string body,int status=200,string type="text/plain; charset=utf-8"){byte[] bytes=Encoding.UTF8.GetBytes(body);string headers="HTTP/1.1 "+status+" OK\r\nContent-Type: "+type+"\r\nContent-Length: "+bytes.Length+"\r\nConnection: close\r\n\r\n";byte[] head=Encoding.ASCII.GetBytes(headers);stream.Write(head,0,head.Length);stream.Write(bytes,0,bytes.Length);}
 string MobilePage(){return @"<!doctype html><meta name='viewport' content='width=device-width,initial-scale=1'><style>body{margin:0;padding:24px;background:radial-gradient(circle at 15% 0,#49368a 0,transparent 35%),linear-gradient(145deg,#0d0f18,#171224 58%,#0c1220);color:#fff;font:16px Segoe UI}main{max-width:420px;margin:auto}.brand{color:#c5b7ff;font-size:12px;font-weight:bold;letter-spacing:1px}.brand b{display:block;color:#fff;font-size:26px;margin-top:5px}.sub,.note{color:#aaa6bd}.card{background:#1a1c2acc;border:1px solid #ffffff14;border-radius:22px;padding:19px;margin-top:20px}.colors{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.colors button{height:58px;border:0;border-radius:14px;font-weight:bold}.field{box-sizing:border-box;width:100%;height:48px;margin-top:12px;padding:12px;border:1px solid #ffffff18;border-radius:13px;background:#10121c;color:#fff;font:inherit}.apply{width:100%;height:53px;margin-top:16px;border:0;border-radius:15px;background:linear-gradient(105deg,#b192ff,#7654e8);color:#171122;font-weight:900}.status{display:flex;gap:8px;align-items:center;margin:20px 4px;color:#aaa6bd;font-size:12px}.dot{width:8px;height:8px;border-radius:50%;background:#49d796;box-shadow:0 0 12px #49d796}</style><main><div class='brand'>THEBESTRGB<b>Controle do setup</b></div><p class='sub'>Controle remoto da sua iluminação.</p><section class='card'><div class='colors'><button onclick='go(&quot;ffffff&quot;)'>Branco</button><button style='background:#e84657;color:#fff' onclick='go(&quot;ff304b&quot;)'>Vermelho</button><button style='background:#3f9df5;color:#fff' onclick='go(&quot;4bb8ff&quot;)'>Azul</button><button style='background:#28ba7d;color:#fff' onclick='go(&quot;20e497&quot;)'>Verde</button><button style='background:#8758e9;color:#fff' onclick='go(&quot;a060ff&quot;)'>Roxo</button><button style='background:#ee9838;color:#fff' onclick='go(&quot;ff9b38&quot;)'>Laranja</button></div><input class='field' id='color' value='#FFFFFF'><select class='field' id='mode'><option value='0'>Cor fixa</option><option value='1'>Arco-íris</option><option value='2'>Respiração</option><option value='4'>Onda pelo setup</option><option value='16'>Elétrica</option></select><button class='apply' onclick='apply()'>Aplicar iluminação</button><p id='note' class='note'></p></section><div class='status'><i class='dot'></i>Conectado ao ThebestRGB neste PC</div></main><script>function go(x){color.value='#'+x;apply()}function apply(){note.textContent='Aplicando…';fetch('/set?color='+encodeURIComponent(color.value)+'&mode='+mode.value).then(()=>note.textContent='Iluminação aplicada.')}</script>";}
 void ShowMobileRemote(){if(string.IsNullOrEmpty(mobileAddress)){MessageBox.Show(this,"Não foi possível iniciar o controle pelo celular nesta rede.","ThebestRGB");return;}using(var dialog=new Form{Text="ThebestRGB / Controle pelo celular",ClientSize=new Size(510,218),BackColor=surface,ForeColor=Color.White,Font=new Font("Segoe UI",10),StartPosition=FormStartPosition.CenterParent,MaximizeBox=false,MinimizeBox=false}){dialog.Controls.Add(new Label{Text="No celular, conectado ao mesmo Wi-Fi, abra:",AutoSize=true,Location=new Point(24,34)});var address=new TextBox{ReadOnly=true,Multiline=true,Text=mobileAddress,BackColor=Color.FromArgb(35,38,50),ForeColor=Color.White,BorderStyle=BorderStyle.FixedSingle};address.SetBounds(24,65,462,50);dialog.Controls.Add(address);dialog.Controls.Add(new Label{Text="Funciona somente nesta rede. Mantenha o ThebestRGB aberto neste PC.",ForeColor=Muted,Size=new Size(462,28),Location=new Point(26,128)});var close=Button("Fechar",surface);close.DialogResult=DialogResult.OK;close.SetBounds(356,170,130,32);dialog.Controls.Add(close);dialog.AcceptButton=close;DarkDialogChrome.Attach(dialog,dialog.Text);dialog.ShowDialog(this);}}
 void StopMobileRemote(){try{if(mobileStop!=null)mobileStop.Cancel();if(mobileListener!=null)mobileListener.Stop();}catch{}}
}
